"""Shared dataset and dataloader utilities."""

import numpy as np
import pickle
from torch.utils.data import Dataset


def load_data(data_dir):
    """Load the interaction pickle generated by data/process.py from its file path."""
    with open(data_dir, "rb") as f:
        item_size, encoder_seq_len, user_seq = pickle.load(f)
    print(f"item_size: {item_size}, user_size: {len(user_seq)}, encoder_seq_len: {encoder_seq_len}")
    return item_size, encoder_seq_len, user_seq


def split_data(user_seq, only_test=False):
    """Split user sequences into val/test. Train data is handled by dataset classes directly.

    Returns:
        only_test=True:  test_seq
        only_test=False: valid_seq, test_seq
    """
    valid_seq, test_seq = [], []
    for user, seq in user_seq.items():
        test_seq.append([seq[:-1], [seq[-1]]])
        if not only_test:
            valid_seq.append([seq[:-2], [seq[-2]]])

    if only_test:
        return test_seq
    return valid_seq, test_seq


class RecDataset(Dataset):
    """Evaluation dataset (val/test): pre-split [history, [target]] pairs."""
    def __init__(self, data, item_size, encoder_seq_len):
        super().__init__()
        self.data = data
        self.item_size = item_size + 1  # +1 for padding at index 0
        self.encoder_seq_len = encoder_seq_len

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        out = {}
        target_items = self.data[idx][1]
        out['target_id'] = np.array(target_items, dtype=np.int64)

        history = self.data[idx][0]
        if len(history) < self.encoder_seq_len:
            # right pad with zeros
            condition = history + [0] * (self.encoder_seq_len - len(history))
        else:
            condition = history[-self.encoder_seq_len:]
        out['condition'] = np.array(condition, dtype=np.int64)

        history_mask = np.ones(self.item_size, dtype=np.float32)
        history_mask[history] = 0.0
        out['mask'] = history_mask

        return out


class LazyRecTrainDataset(Dataset):
    """Memory-efficient training dataset: stores only (user_idx, position) indices.

    Generates the same data as the old split_data + RecDataset approach,
    but without materializing all prefix subsequences in memory.
    Memory: ~24.5M × 16B ≈ 0.4GB instead of ~50-140GB for ML-25M.
    """
    def __init__(self, user_seq, encoder_seq_len):
        super().__init__()
        self.encoder_seq_len = encoder_seq_len
        # Store sequences as list for index access
        self.seqs = []
        self.indices = []  # (seq_idx, target_pos)
        for seq_idx, (user, seq) in enumerate(user_seq.items()):
            self.seqs.append(seq)
            # last two items are reserved for validation and test
            for i in range(1, len(seq) - 2):
                self.indices.append((seq_idx, i))

    def __len__(self):
        return len(self.indices)

    def __getitem__(self, idx):
        seq_idx, pos = self.indices[idx]
        seq = self.seqs[seq_idx]
        history = seq[:pos]
        target_items = [seq[pos]]

        out = {}
        out['target_id'] = np.array(target_items, dtype=np.int64)

        if len(history) < self.encoder_seq_len:
            # right pad with zeros
            condition = history + [0] * (self.encoder_seq_len - len(history))
        else:
            condition = history[-self.encoder_seq_len:]
        out['condition'] = np.array(condition, dtype=np.int64)

        return out